package kw.urtv.home;
import android.content.*;import android.database.*;import android.net.Uri;import android.os.ParcelFileDescriptor;import java.io.*;import org.json.*;import java.util.*;import kw.urtv.shared.ContentPolicy;
/** Signature-only snapshot and tiny cached logos. No network is performed by this provider. */
public final class FootballProvider extends ContentProvider {
 public boolean onCreate(){return true;}
 public Cursor query(Uri u,String[] p,String s,String[] a,String sort){MatrixCursor c=new MatrixCursor(new String[]{"matches"});JSONArray out=new JSONArray();android.content.SharedPreferences prefs=getContext().getSharedPreferences("football",0);Set<String> seen=new HashSet<>();if(prefs.getBoolean("enabled",false))try{JSONArray favorites=new JSONArray(prefs.getString("favorites","[]"));for(int i=0;i<Math.min(6,favorites.length());i++){JSONObject f=favorites.getJSONObject(i);if(!ContentPolicy.team(f.optString("id"),f.toString()))continue;JSONArray rows=new JSONArray(prefs.getString("cache:"+f.getString("id"),"[]"));boolean past=false,future=false;for(int k=0;k<rows.length();k++){JSONObject e=rows.getJSONObject(k);if(!FootballResults.allowed(e)||!kw.urtv.shared.MatchVisibility.visible(e.optString("state"),e.optString("status"),java.time.Instant.parse(e.getString("date")),java.time.Instant.now()))continue;boolean done=e.optString("state").equals("post");if(done?past:future)continue;if(done)past=true;else future=true;if(seen.add(e.getString("id")))out.put(new JSONObject(e.toString()).put("updated",prefs.getLong("updated:"+f.getString("id"),0)));}}}catch(Exception ignored){}c.addRow(new Object[]{out.toString()});return c;}
 public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{String id=uri.getLastPathSegment();if(!"r".equals(mode)||!ContentPolicy.team(id,""))throw new FileNotFoundException();return ParcelFileDescriptor.open(new File(getContext().getCacheDir(),"football-logos/"+id+".png"),ParcelFileDescriptor.MODE_READ_ONLY);}
 public String getType(Uri u){return "image/png";}public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}
}
